import os, re

d = os.environ['RLM_SESSION_DIR']
log_file = f"{d}.jsonl"

print(f"Looking for log at: {log_file}")
try:
    with open(log_file, 'r') as f:
        content = f.read()
    print(f"Log loaded, length: {len(content)}")

    # Parse demos
    demos = []
    current_key = None
    current_rows = []
    cur_rows = 0
    cur_cols = 0

    for line in content.split('\n'):
        if 'Demo pair ' in line or 'Test input' in line:
            if current_key is not None:
                if current_rows > 0 and cur_rows == cur_cols:
                    demos.append({'key': current_key, 'rows': current_rows})
            if 'Test input' in line:
                m = re.search(r'Test input \((\d+)x(\d+)\):', line)
                if m:
                    current_key = 'Test input'
                    cur_rows = int(m.group(2))
            else:
                m = re.search(r'(Demo pair \d+ ?(?:input|output)) \((\d+)x(\d+)\):', line)
                if m:
                    current_key = m.group(1)
                    cur_rows = int(m.group(3))
            cur_cols = int(m.group(2)) if 'Test input' not in line else int(m.group(1))
            current_rows = []
        elif line.strip():
            current_rows.append(line.strip())

    print(f"\nParsed {len(demos)} demo pairs found")
    for d in demos:
        print(f"  {d['key']}: {d['rows']}")

except Exception as e:
    import traceback
    traceback.print_exc()

